import{_ as o,a0 as l,w as d,s as p,ao as r,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 pass 密碼管理器管理你的密碼 | LCTT x X-CMD","titleTemplate":false,"description":"使用 pass 密碼管理器管理你的密碼 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 pass 密碼管理器管理你的密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 pass 密碼管理器管理你的密碼 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171121 How to organize your passwords using pass password manager","title":"使用 pass 密碼管理器管理你的密碼","tag":"201803","desc":""},"relativePath":"201803/20171121 How to organize your passwords using pass password manager.md","filePath":"[post].md"}'),h={name:"201803/20171121 How to organize your passwords using pass password manager.md"};function c(g,s,k,b,u,f){const e=l("Link");return d(),p("div",null,[s[13]||(s[13]=r(`<h1 id="使用-pass-密碼管理器管理你的密碼" tabindex="-1">使用 pass 密碼管理器管理你的密碼 <a class="header-anchor" href="#使用-pass-密碼管理器管理你的密碼" aria-label="Permalink to “使用 pass 密碼管理器管理你的密碼”">​</a></h1><h3 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to “目標”">​</a></h3><p>學習在 Linux 上使用 pass 密碼管理器來管理你的密碼</p><h3 id="條件" tabindex="-1">條件 <a class="header-anchor" href="#條件" aria-label="Permalink to “條件”">​</a></h3><ul><li>需要 root 權限來安裝需要的包</li></ul><h3 id="難度" tabindex="-1">難度 <a class="header-anchor" href="#難度" aria-label="Permalink to “難度”">​</a></h3><p>簡單</p><h3 id="約定" tabindex="-1">約定 <a class="header-anchor" href="#約定" aria-label="Permalink to “約定”">​</a></h3><ul><li><code>#</code> - 執行指定命令需要 root 權限，可以是直接使用 root 用户來執行或者使用 <code>sudo</code> 命令來執行</li><li><code>$</code> - 使用普通的非特權用户執行指定命令</li></ul><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>如果你有根據不同的意圖設置不同密碼的好習慣，你可能已經感受到需要一個密碼管理器的必要性了。在 Linux 上有很多選擇，可以是專有軟件（如果你敢用的話）也可以是開源軟件。如果你跟我一樣喜歡簡潔的話，你可能會對 <code>pass</code> 感興趣。</p><h3 id="第一步" tabindex="-1">第一步 <a class="header-anchor" href="#第一步" aria-label="Permalink to “第一步”">​</a></h3><p>pass 作為一個密碼管理器，其實際上是一些你可能早已每天使用的、可信賴且實用的工具的一種封裝，比如 <code>gpg</code> 和 <code>git</code> 。雖然它也有圖形界面，但它專門設計能成在命令列下工作的：因此它也可以在 headless 機器上工作（LCTT 譯註：根據 wikipedia 的説法，所謂 headless 是指沒有顯示器、鍵盤和鼠標的機器，一般通過網絡鏈接來控制）。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>pass 在主流的 Linux 發行版中都是可用的，你可以通過包管理器安裝：</p><h4 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install pass</span></span></code></pre></div><h4 id="rhel-和-centos" tabindex="-1">RHEL 和 CentOS <a class="header-anchor" href="#rhel-和-centos" aria-label="Permalink to “RHEL 和 CentOS”">​</a></h4><p>pass 不在官方倉庫中，但你可以從 <code>epel</code> 中獲取道它。要在 CentOS7 上啓用後面這個源，只需要執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install epel-release</span></span></code></pre></div><p>然而在 Red Hat 企業版的 Linux 上，這個額外的源是不可用的；你需要從 EPEL 官方網站上下載它。</p><h4 id="debian-和-ubuntu" tabindex="-1">Debian 和 Ubuntu <a class="header-anchor" href="#debian-和-ubuntu" aria-label="Permalink to “Debian 和 Ubuntu”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install pass</span></span></code></pre></div><h4 id="arch-linux" tabindex="-1">Arch Linux <a class="header-anchor" href="#arch-linux" aria-label="Permalink to “Arch Linux”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S pass</span></span></code></pre></div><h3 id="初始化密碼倉庫" tabindex="-1">初始化密碼倉庫 <a class="header-anchor" href="#初始化密碼倉庫" aria-label="Permalink to “初始化密碼倉庫”">​</a></h3><p>安裝好 <code>pass</code> 後，就可以開始使用和配置它了。首先，由於 <code>pass</code> 依賴於 <code>gpg</code> 來對我們的密碼進行加密並以安全的方式進行存儲，我們必須準備好一個 gpg 密鑰對。</p><p>首先我們要初始化密碼倉庫：這就是一個用來存放 gpg 加密後的密碼的目錄。默認情況下它會在你的 <code>$HOME</code> 創建一個隱藏目錄，不過你也可以通過使用 <code>PASSWORD_STORE_DIR</code> 這一環境變量來指定另一個路徑。讓我們運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass init</span></span></code></pre></div><p>然後 <code>password-store</code> 目錄就創建好了。現在，讓我們來存儲我們第一個密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass edit mysite</span></span></code></pre></div><p>這會打開默認文本編輯器，我麼只需要輸入密碼就可以了。輸入的內容會用 gpg 加密並存儲為密碼倉庫目錄中的 <code>mysite.gpg</code> 文件。</p><p><code>pass</code> 以目錄樹的形式存儲加密後的文件，也就是説我們可以在邏輯上將多個文件放在子目錄中以實現更好的組織形式，我們只需要在創建文件時指定存在哪個目錄下就行了，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass edit foo/bar</span></span></code></pre></div><p>跟上面的命令一樣，它也會讓你輸入密碼，但是創建的文件是放在密碼倉庫目錄下的 <code>foo</code> 子目錄中的。要查看文件組織結構，只需要不帶任何參數運行 <code>pass</code> 命令即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass</span></span>
<span class="line"><span>Password Store</span></span>
<span class="line"><span>├── foo</span></span>
<span class="line"><span>│   └── bar</span></span>
<span class="line"><span>└── mysite</span></span></code></pre></div><p>若想修改密碼，只需要重複創建密碼的操作就行了。</p><h3 id="獲取密碼" tabindex="-1">獲取密碼 <a class="header-anchor" href="#獲取密碼" aria-label="Permalink to “獲取密碼”">​</a></h3><p>有兩種方法可以獲取密碼：第一種會顯示密碼到終端上，方法是運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass mysite</span></span></code></pre></div><p>然而更好的方法是使用 <code>-c</code> 選項讓 <code>pass</code> 將密碼直接拷貝到剪切板上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass -c mysite</span></span></code></pre></div><p>這種情況下剪切板中的內容會在 <code>45</code> 秒後自動清除。兩種方法都會要求你輸入 gpg 密碼。</p><h3 id="生成密碼" tabindex="-1">生成密碼 <a class="header-anchor" href="#生成密碼" aria-label="Permalink to “生成密碼”">​</a></h3><p><code>pass</code> 也可以為我們自動生成（並自動存儲）安全密碼。假設我們想要生成一個由 15 個字符組成的密碼：包含字母，數字和特殊符號，其命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass generate mysite 15</span></span></code></pre></div><p>若希望密碼只包含字母和數字則可以是使用 <code>--no-symbols</code> 選項。生成的密碼會顯示在屏幕上。也可以通過 <code>--clip</code> 或 <code>-c</code> 選項讓 <code>pass</code> 把密碼直接拷貝到剪切板中。通過使用 <code>-q</code> 或 <code>--qrcode</code> 選項來生成二維碼：</p><p><img src="https://linuxconfig.org/images/pass-manager-qrcode.png" alt="qrcode"></p><p>從上面的截屏中可看出，生成了一個二維碼，不過由於運行該命令時 <code>mysite</code> 的密碼已經存在了，<code>pass</code> 會提示我們確認是否要覆蓋原密碼。</p><p><code>pass</code> 使用 <code>/dev/urandom</code> 設備作為（偽）隨機數據生成器來生成密碼，同時它使用 <code>xclip</code> 工具來將密碼拷貝到粘帖板中，而使用 <code>qrencode</code> 來將密碼以二維碼的形式顯示出來。在我看來，這種模組化的設計正是它最大的優勢：它並不重複造輪子，而只是將常用的工具包裝起來完成任務。</p><p>你也可以使用 <code>pass mv</code>、<code>pass cp</code> 和 <code>pass rm</code> 來重命名、拷貝和刪除密碼倉庫中的文件。</p><h3 id="將密碼倉庫變成-git-倉庫" tabindex="-1">將密碼倉庫變成 git 倉庫 <a class="header-anchor" href="#將密碼倉庫變成-git-倉庫" aria-label="Permalink to “將密碼倉庫變成 git 倉庫”">​</a></h3><p><code>pass</code> 另一個很棒的功能就是可以將密碼倉庫當成 git 倉庫來用：通過版本管理系統能讓我們管理密碼更方便。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass git init</span></span></code></pre></div><p>這會創建 git 倉庫，並自動提交所有已存在的文件。下一步就是指定跟蹤的遠程倉庫了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass git remote add &lt;name&gt; &lt;url&gt;</span></span></code></pre></div><p>我們可以把這個密碼倉庫當成普通倉庫來用。唯一的不同點在於每次我們新增或修改一個密碼，<code>pass</code> 都會自動將該文件加入索引並創建一個提交。</p><p><code>pass</code> 有一個叫做 <code>qtpass</code> 的圖形界面，而且也支持 Windows 和 MacOs。通過使用 <code>PassFF</code> 插件，它還能獲取 firefox 中存儲的密碼。在它的項目網站上可以查看更多詳細信息。試一下 <code>pass</code> 吧，你不會失望的！</p><hr>`,59)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://linuxconfig.org/how-to-organize-your-passwords-using-pass-password-manager"},{default:t(()=>[...s[0]||(s[0]=[a("https://linuxconfig.org/how-to-organize-your-passwords-using-pass-password-manager",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=a("作者：",-1)),i(e,{href:"https://linuxconfig.org"},{default:t(()=>[...s[2]||(s[2]=[a("Egidio Docile",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),i(e,{href:"https://github.com/locez"},{default:t(()=>[...s[4]||(s[4]=[a("Locez",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const C=o(h,[["render",c]]);export{y as __pageData,C as default};
